// Brass & Ballast service worker (DESIGN §9).
//
// Offline-first: every same-origin GET is answered from the precache when possible. The
// precache list and version come from precache-manifest.js (generated by
// tools/gen-precache.mjs). A new version installs alongside the old one and waits; the page
// shows an update toast and posts SKIP_WAITING when the player agrees (js/pwa.js).

importScripts('precache-manifest.js');

const CACHE_PREFIX = 'brass-ballast-';
const CACHE = CACHE_PREFIX + self.PRECACHE.version;
const INDEX_URL = new URL('index.html', self.location.href).href;

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      // cache:'reload' bypasses the HTTP cache so the precache never holds stale bytes.
      // addAll is all-or-nothing: a missing file fails the install rather than shipping a
      // half-cached version.
      await cache.addAll(self.PRECACHE.files.map((f) => new Request(f, { cache: 'reload' })));
    })()
  );
  // Deliberately no skipWaiting(): the page decides when to switch (see SKIP_WAITING below).
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names
          .filter((n) => n.startsWith(CACHE_PREFIX) && n !== CACHE)
          .map((n) => caches.delete(n))
      );
      await self.clients.claim();
    })()
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  if (req.mode === 'navigate') {
    event.respondWith(handleNavigation(req));
    return;
  }
  event.respondWith(handleAsset(event, req));
});

/** Navigations: serve the cached shell regardless of query string (?debug=1 etc.). */
async function handleNavigation(req) {
  const cache = await caches.open(CACHE);
  const shell = await cache.match(INDEX_URL, { ignoreSearch: true });
  if (shell) return shell;
  try {
    return await fetch(req);
  } catch {
    return new Response('Brass & Ballast is not cached yet. Reconnect once to install it.', {
      status: 503,
      headers: { 'Content-Type': 'text/plain; charset=utf-8' },
    });
  }
}

/** Everything else: cache first, then network, filling the cache with good responses. */
async function handleAsset(event, req) {
  const cache = await caches.open(CACHE);
  const hit = await cache.match(req, { ignoreSearch: true });
  if (hit) return hit;

  const res = await fetch(req);
  if (res.ok && res.type === 'basic') {
    event.waitUntil(cache.put(req, res.clone()).catch(() => {}));
  }
  return res;
}

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});
